 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready')
 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,rows=[],check=(name,passed,details)=>rows.push({name,passed,details});const setup=id=>{A.start(id,'ryu','training','classic',42);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('infinite').checked=false;A.teleport(0,560);A.teleport(1,710);};const sim=f=>JSON.stringify([f.x,f.y,f.hp,f.drive,f.state,f.stateT,f.attack?.t,f.attack?.armor,f.combo,G.actionTick]);
 for(const id of INK.Schema.CHARACTERS){const views=[];for(const low of [false,true]){setup(id);A.press(0,'left');if(low)A.press(0,'down');A.tryMove(1,low?'cMK':'sMP');const f=A.fighters[0];for(let i=0;i<45&&f.state!=='block';i++)A.step();const before=sim(f),pose=A.visualPose(f),rig=INK.Runtime.visualRig(f,pose),profile=INK.GuardBody.profiles[id],bridge=f._inkStateVisualBlend;for(let i=0;i<4;i++){A.visualPose(f);A.render();}check(id+(low?' low':' high')+' real block has guard hands and pure render',f.state==='block'&&f._inkReaction?.guard&&pose.handFront===profile.front&&pose.handRear===profile.rear&&pose.expression==='guard'&&sim(f)===before,{hands:[pose.handFront,pose.handRear],state:f.state});check(id+(low?' low':' high')+' first-contact lead arm bridge is released',bridge?.jointBridge.offsets.frontArm.every(v=>v===0)&&bridge?.jointBridge.velocities.frontArm.every(v=>v===0)&&!('fw'in bridge.poseBridge.offsets));views.push({front:rig.frontArm[2],rear:rig.rearArm[2]});}check(id+' high and low resolved guard skeletons differ',Math.hypot(views[0].front[0]-views[1].front[0],views[0].front[1]-views[1].front[1])>10,{views});}
 setup('ken');const f=A.fighters[0],enemy=A.fighters[1];A.tryMove(0,'DI');const original=f.attack;A.tryMove(1,'sLP');const incoming=enemy.attack;for(let i=0;i<30&&!f._inkReaction?.armor;i++)A.step();const r=f._inkReaction,before=sim(f),pose=A.visualPose(f);A.render();check('Real jab triggers immutable armor event without hit confirm',r?.armor&&Object.isFrozen(r)&&Object.isFrozen(r.point)&&G.lastCombatEvent?.type==='armor'&&!incoming.confirmed&&enemy.combo===0&&f.attack===original&&f.state==='attack',{event:G.lastCombatEvent,confirm:incoming.confirmed,combo:enemy.combo,armor:original.armor});check('Armor render preserves attack and frozen sampling',pose.expression==='brace'&&sim(f)===before&&JSON.stringify(A.visualPose(f))===JSON.stringify(pose),{handFront:pose.handFront,open:pose.open});while(G.hitstop)A.step();const t=original.t;A.step();check('Armored attack resumes rather than becoming hitstun',f.attack===original&&original.t>t&&f.state==='attack');return rows;}''');b.close()
